// The TOP-LEVEL, hoisted `legit-nested@1`. Same package name as the copy nested under
// `legit-host`, different version — the ordinary npm version-conflict layout. It is here so
// the two copies can be shown to be DISTINCT principals: granting one must not grant the other.
const path = require("node:path");

const SECRET = "FORGE_FIXTURE_SECRET";
const SECRET_FILE = path.join(__dirname, "..", "..", "secret.txt");

module.exports = function topLevelLibrary() {
  const out = { env: process.env[SECRET], fs: undefined };
  try {
    out.fs = require("node:fs").readFileSync(SECRET_FILE, "utf8").trim();
  } catch (err) {
    out.fs = err && err.name === "CapabilityError" ? `DENIED:${err.pkg}` : `THREW:${err.message}`;
  }
  return out;
};
